int distance_to_int(const EnemyDistance distance) {
    return ([&]() -> int {
    if (distance == EnemyDistance::ED_CLOSE) {
        return 0;
    }
    if (distance == EnemyDistance::ED_SHORT_JUMPSLASH) {
        return 1;
    }
    if (distance == EnemyDistance::ED_MASTER_SWORD_JUMPSLASH) {
        return 2;
    }
    if (distance == EnemyDistance::ED_LONG_JUMPSLASH) {
        return 3;
    }
    if (distance == EnemyDistance::ED_BOMB_THROW) {
        return 4;
    }
    if (distance == EnemyDistance::ED_BOOMERANG) {
        return 5;
    }
    if (distance == EnemyDistance::ED_HOOKSHOT) {
        return 6;
    }
    if (distance == EnemyDistance::ED_LONGSHOT) {
        return 7;
    }
    if (distance == EnemyDistance::ED_FAR) {
        return 8;
    }
    return int{};
}());
}

